# Building a Codebase Search Agent with codx-junior

I'll show you how to build an agent that can search through your codebase at `/home/codx-junior-projects/codx-junior`.

## Architecture Overview

```mermaid
graph TD
    A[User Query] --> B[Search Agent]
    B --> C{Search Strategy}
    C --> D[File Search]
    C --> E[Code Search/grep]
    C --> F[Semantic Search]
    D --> G[Results Aggregator]
    E --> G
    F --> G
    G --> H[LLM Analysis]
    H --> I[Response]
```

## Implementation

### 1. Core Search Tools

```python /home/codx-junior-projects/codx-junior/agents/search_tools.py
import os
import subprocess
import fnmatch
from pathlib import Path
from typing import List, Dict, Optional

CODEBASE_PATH = "/home/codx-junior-projects/codx-junior"

def search_files_by_name(pattern: str, base_path: str = CODEBASE_PATH) -> List[str]:
    """Search files by name pattern"""
    matches = []
    for root, dirs, files in os.walk(base_path):
        # Skip hidden and common ignored directories
        dirs[:] = [d for d in dirs if not d.startswith('.') 
                   and d not in ['node_modules', '__pycache__', '.git', 'venv']]
        for filename in files:
            if fnmatch.fnmatch(filename, pattern):
                matches.append(os.path.join(root, filename))
    return matches

def search_code_content(
    query: str, 
    base_path: str = CODEBASE_PATH,
    file_extensions: Optional[List[str]] = None,
    case_sensitive: bool = False
) -> List[Dict]:
    """Search for text/code patterns within files"""
    results = []

    # Build grep command
    grep_args = ["grep", "-rn", "--include"]

    extensions = file_extensions or ["*.py", "*.js", "*.ts", "*.jsx", "*.tsx", "*.md"]

    for ext in extensions:
        cmd = ["grep", "-rn"]
        if not case_sensitive:
            cmd.append("-i")
        cmd.extend(["--include", ext, query, base_path])

        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.stdout:
                for line in result.stdout.strip().split('\n'):
                    if ':' in line:
                        parts = line.split(':', 2)
                        if len(parts) >= 3:
                            results.append({
                                "file": parts[0],
                                "line": parts[1],
                                "content": parts[2].strip()
                            })
        except subprocess.TimeoutExpired:
            pass

    return results

def get_file_content(file_path: str, max_lines: int = 200) -> Dict:
    """Read file content with metadata"""
    try:
        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()

        return {
            "path": file_path,
            "total_lines": len(lines),
            "content": ''.join(lines[:max_lines]),
            "truncated": len(lines) > max_lines
        }
    except Exception as e:
        return {"error": str(e), "path": file_path}

def get_directory_structure(
    base_path: str = CODEBASE_PATH, 
    max_depth: int = 3
) -> str:
    """Get project directory tree"""
    result = []

    def walk_dir(path, depth=0, prefix=""):
        if depth > max_depth:
            return

        try:
            items = sorted(os.listdir(path))
        except PermissionError:
            return

        for i, item in enumerate(items):
            if item.startswith('.') or item in ['node_modules', '__pycache__', 'venv']:
                continue

            is_last = i == len(items) - 1
            connector = "└── " if is_last else "├── "
            result.append(f"{prefix}{connector}{item}")

            item_path = os.path.join(path, item)
            if os.path.isdir(item_path):
                extension = "    " if is_last else "│   "
                walk_dir(item_path, depth + 1, prefix + extension)

    result.append(base_path)
    walk_dir(base_path)
    return '\n'.join(result)

def search_by_regex(
    pattern: str, 
    base_path: str = CODEBASE_PATH,
    file_extensions: Optional[List[str]] = None
) -> List[Dict]:
    """Search using regex patterns"""
    extensions = file_extensions or ["*.py", "*.js", "*.ts"]
    results = []

    for ext in extensions:
        cmd = ["grep", "-rn", "-E", "--include", ext, pattern, base_path]
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.stdout:
                for line in result.stdout.strip().split('\n'):
                    parts = line.split(':', 2)
                    if len(parts) >= 3:
                        results.append({
                            "file": parts[0],
                            "line": parts[1],
                            "content": parts[2].strip(),
                            "pattern": pattern
                        })
        except subprocess.TimeoutExpired:
            pass

    return results
```

### 2. Search Agent

```python /home/codx-junior-projects/codx-junior/agents/codebase_agent.py
