    search_code_content,
    get_file_content,
    get_directory_structure,
    search_by_regex
)

# Define agent tools schema (OpenAI function calling format)
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "search_files_by_name",
            "description": "Search for files by name pattern in the codebase. Use wildcards like *.py, *config*, etc.",
            "parameters": {
                "type": "object",
                "properties": {
                    "pattern": {
                        "type": "string",
