                        "type": "string",
                        "description": "Regex pattern to search for (e.g., 'def \\w+_agent', 'class.*Agent')"
                    },
                    "file_extensions": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "File extensions to include"
                    }
                },
                "required": ["pattern"]
            }
        }
    }
]

# Tool execution dispatcher
def execute_tool(tool_name: str, tool_args: Dict) -> Any:
    tool_map = {
        "search_files_by_name": search_files_by_name,
        "search_code_content": search_code_content,
        "get_file_content": get_file_content,
        "get_directory_structure": get_directory_structure,
        "search_by_regex": search_by_regex
    }

    if tool_name not in tool_map:
        return {"error": f"Unknown tool: {tool_name}"}

    return tool_map[tool_name](**tool_args)


class CodebaseSearchAgent:
    def __init__(self, llm_client, model: str = "gpt-4"):
        self.client = llm_client
        self.model = model
        self.system_prompt = """You are a codebase search assistant for the codx-junior project.

Your job is to help developers find code, understand the structure, and locate relevant files.

Project path: /home/codx-junior-projects/codx-junior

Guidelines:
- Start by understanding the directory structure if needed
- Use targeted searches to find relevant code
- When you find files, read their content to provide detailed answers
- Always cite the file path and line number in your responses
- Chain multiple searches to build a complete picture
- Be precise and helpful in explaining what you found
"""
        self.conversation_history = []

    def run(self, user_query: str, max_iterations: int = 10) -> str:
        """Run the agent with agentic loop"""

        self.conversation_history.append({
            "role": "user",
            "content": user_query
        })

        iteration = 0

        while iteration < max_iterations:
            iteration += 1

            # Call LLM
            response = self.client.chat.completions.create(
                model=self.model,
                messages=[
                    {"role": "system", "content": self.system_prompt},
                    *self.conversation_history
                ],
                tools=TOOLS,
                tool_choice="auto"
            )

            message = response.choices[0].message

            # No more tool calls - we have the final answer
            if not message.tool_calls:
                final_response = message.content
                self.conversation_history.append({
                    "role": "assistant",
                    "content": final_response
                })
                return final_response

            # Execute tool calls
            self.conversation_history.append(message)

            for tool_call in message.tool_calls:
                import json
                tool_name = tool_call.function.name
                tool_args = json.loads(tool_call.function.arguments)

                print(f"🔍 Executing: {tool_name}({tool_args})")

                tool_result = execute_tool(tool_name, tool_args)

                self.conversation_history.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": str(tool_result)
                })

        return "Max iterations reached. Please refine your query."
