import os
import json
from pathlib import Path
from typing import List, Dict
import hashlib

CODEBASE_PATH = "/home/codx-junior-projects/codx-junior"
INDEX_FILE = "/tmp/codebase_index.json"

def build_code_index(
    base_path: str = CODEBASE_PATH,
    extensions: List[str] = ['.py', '.js', '.ts', '.jsx', '.tsx']
) -> List[Dict]:
    """Build an index of all code files with their content chunks"""

    index = []

    for root, dirs, files in os.walk(base_path):
        dirs[:] = [d for d in dirs 
                   if not d.startswith('.') 
                   and d not in ['node_modules', '__pycache__', '.git', 'venv', 'dist']]

        for file in files:
            if any(file.endswith(ext) for ext in extensions):
                file_path = os.path.join(root, file)

                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()

                    # Chunk the file into sections
                    chunks = chunk_code(content, file_path)
                    index.extend(chunks)

                except Exception as e:
                    print(f"Error indexing {file_path}: {e}")

    # Save index
    with open(INDEX_FILE, 'w') as f:
        json.dump(index, f)

    print(f"Indexed {len(index)} code chunks from {base_path}")
    return index

def chunk_code(content: str, file_path: str, chunk_size: int = 50) -> List[Dict]:
    """Split code into meaningful chunks"""
    lines = content.split('\n')
    chunks = []

    for i in range(0, len(lines), chunk_size):
        chunk_lines = lines[i:i + chunk_size]
        chunk_content = '\n'.join(chunk_lines)

        if chunk_content.strip():
            chunks.append({
                "file": file_path,
                "start_line": i + 1,
                "end_line": min(i + chunk_size, len(lines)),
                "content": chunk_content,
                "id": hashlib.md5(f"{file_path}:{i}".encode()).hexdigest()
            })

    return chunks

def semantic_search_with_embeddings(
    query: str,
    llm_client,
    top_k: int = 5
) -> List[Dict]:
    """
    Use embeddings for semantic code search
    Requires: pip install openai numpy
    """
    import numpy as np

    # Load index
    if not os.path.exists(INDEX_FILE):
        build_code_index()

    with open(INDEX_FILE, 'r') as f:
        index = json.load(f)

    # Get query embedding
    query_embedding = llm_client.embeddings.create(
        input=query,
        model="text-embedding-3-small"
    ).data[0].embedding

    # Get embeddings for all chunks (in production, cache these!)
    results_with_scores = []

    for chunk in index:
        chunk_embedding = llm_client.embeddings.create(
            input=chunk['content'][:2000],  # Limit content length
            model="text-embedding-3-small"
        ).data[0].embedding

        # Cosine similarity
        similarity = np.dot(query_embedding, chunk_embedding) / (
            np.linalg.norm(query_embedding) * np.linalg.norm(chunk_embedding)
        )

        results_with_scores.append({
            **chunk,
            "similarity": float(similarity)
        })

    # Sort by similarity and return top_k
    results_with_scores.sort(key=lambda x: x['similarity'], reverse=True)
    return results_with_scores[:top_k]
